#!/usr/bin/env node
/* Canonical browser object contract + read-only reader: deterministic bundle.
 * Two source modules are authoritative; the exported reader stays standalone.
 * Usage: node app/tools/build_reader_bundle.js --write|--check
 */
'use strict';
const fs=require('node:fs'),path=require('node:path');
const web=path.resolve(__dirname,'../web');
const stamp='/* Generated by tools/build_reader_bundle.js; DO NOT edit. */\n';
const contents=stamp+['asset_paths_data.js','asset_paths.js','object_catalog.js','report_reader_core.js'].map(name=>fs.readFileSync(path.join(web,name),'utf8')).join('\n');
const dest=path.join(web,'report_reader.js');
if(process.argv[2]==='--write'){fs.writeFileSync(dest,contents,'utf8');console.log('Generated standalone report reader');}
else if(process.argv[2]==='--check'){
 if(!fs.existsSync(dest)||fs.readFileSync(dest,'utf8')!==contents){console.error('Stale bundled reader');process.exitCode=1;}
 else console.log('Standalone reader bundle up to date');
}else{console.error('Use --write or --check');process.exitCode=2;}
